import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p73_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor bn_scale_fused(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps,
    double scaling_factor
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("bn_scale_fused", &bn_scale_fused, "Fused BN+scale forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void bn_scale_fused_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    float scaling_factor,
    int N, int C, int HW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * HW;
    if (idx >= total) return;
    int c = (idx / HW) % C;
    float mean = __ldg(&running_mean[c]);
    float var  = __ldg(&running_var[c]);
    float gamma = __ldg(&weight[c]);
    float beta  = __ldg(&bias[c]);
    float inv_std = rsqrtf(var + eps);
    float scale_coeff = gamma * inv_std * scaling_factor;
    float shift_coeff = beta * scaling_factor - mean * scale_coeff;
    output[idx] = fmaf(__ldg(&input[idx]), scale_coeff, shift_coeff);
}

__global__ void bn_scale_fused_vec4_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    float scaling_factor,
    int N, int C, int HW
) {
    int base = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    int total = N * C * HW;
    if (base >= total) return;

    // Derive channel from base index; all 4 elements may span at most 2 channels
    // Only use vec4 when all 4 elements are in the same channel
    int c0 = (base / HW) % C;
    int c3 = ((base + 3) / HW) % C;
    if (c0 != c3 || base + 3 >= total) {
        // Scalar fallback for boundary
        for (int i = 0; i < 4 && base + i < total; i++) {
            int c = ((base + i) / HW) % C;
            float mean = __ldg(&running_mean[c]);
            float var  = __ldg(&running_var[c]);
            float gamma = __ldg(&weight[c]);
            float beta  = __ldg(&bias[c]);
            float inv_std = rsqrtf(var + eps);
            float sc = gamma * inv_std * scaling_factor;
            float sh = beta * scaling_factor - mean * sc;
            output[base + i] = fmaf(__ldg(&input[base + i]), sc, sh);
        }
        return;
    }

    float mean = __ldg(&running_mean[c0]);
    float var  = __ldg(&running_var[c0]);
    float gamma = __ldg(&weight[c0]);
    float beta  = __ldg(&bias[c0]);
    float inv_std = rsqrtf(var + eps);
    float sc = gamma * inv_std * scaling_factor;
    float sh = beta * scaling_factor - mean * sc;

    float4 in4 = *reinterpret_cast<const float4*>(input + base);
    float4 out4;
    out4.x = fmaf(in4.x, sc, sh);
    out4.y = fmaf(in4.y, sc, sh);
    out4.z = fmaf(in4.z, sc, sh);
    out4.w = fmaf(in4.w, sc, sh);
    *reinterpret_cast<float4*>(output + base) = out4;
}

torch::Tensor bn_scale_fused(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps,
    double scaling_factor
) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.dim() == 4, "input must be 4D NCHW");

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int HW = H * W;
    int total = N * C * HW;

    auto output = torch::empty_like(input);

    // Use vec4 kernel when HW is divisible by 4 (guarantees within-channel alignment)
    if (HW % 4 == 0) {
        int threads = 256;
        int blocks = (total / 4 + threads - 1) / threads;
        bn_scale_fused_vec4_kernel<<<blocks, threads>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            (float)eps,
            (float)scaling_factor,
            N, C, HW
        );
    } else {
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        bn_scale_fused_kernel<<<blocks, threads>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            (float)eps,
            (float)scaling_factor,
            N, C, HW
        );
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a convolution, applies Batch Normalization, and scales the output.
        """
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if self.training:
            x = self.bn(x)
        else:
            x = _stark_get_extension().bn_scale_fused(
            x.contiguous(),
            self.bn.running_mean.contiguous(),
            self.bn.running_var.contiguous(),
            self.bn.weight.contiguous(),
            self.bn.bias.contiguous(),
            float(self.bn.eps),
            float(self.scaling_factor),
            )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if self.training:
                    x = x * self.scaling_factor
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        return x
        # <<<END_IMPROVE>>>

